import React, { useState, useEffect } from 'react';
import { Modal, ModalHeader, ModalBody, ModalFooter, Row, Col, Input, Label, FormGroup } from 'reactstrap';
import validator from 'validator';
import Select from 'react-select';
import CustomButton from '../../../../components/CustomButton';
import { formResMessage, toLoginEmail } from 'utils/commonFunc';

export const languages = [
  { value: 'EN', label: 'English' },
  { value: 'TA', label: 'Tamil' },
  // { value: 'ML', label: 'Malayalam' },
  // { value: 'TE', label: 'Telugu' },
  // { value: 'KN', label: 'Kannada' },
  // { value: 'HI', label: 'Hindi' },
];

const GuardianFormModal = ({
  isModalOpen,
  saveGuardian,
  updateGuardian,
  guardianUpdateSuccess,
  formModalCloseProp,
  guardian,
}) => {
  const stateObj = {
    data: {
      school: { schoolId: 0 },
      guardianId: 0,
      name: '',
      email: '',
      guardianMobile: '',
      relation: '',
      education: '',
      occupation: '',
      income: '',
      motherTongue: '',
    },
    relationArr: [
      { label: 'FATHER', value: 'FATHER' },
      { label: 'MOTHER', value: 'MOTHER' },
      { label: 'UNCLE', value: 'UNCLE' },
      { label: 'FRIEND', value: 'FRIEND' },
    ],
    errors: {},
    loading: false,
  };

  const [stateVal, setState] = useState(stateObj);

  useEffect(() => {
    if (guardian && Object.keys(guardian).length) {
      setState(prevState => ({
        ...prevState,
        data: {
          school: { schoolId: guardian.school.schoolId },
          education: guardian.education,
          email: guardian.email,
          guardianId: guardian.guardianId,
          guardianMobile: guardian.guardianMobile,
          income: guardian.income,
          name: guardian.name,
          occupation: guardian.occupation,
          relation: guardian.relation,
          motherTongue: guardian.motherTongue || '',
        },
      }));
    }
  }, [guardian]);

  const handleChange = e => {
    e.persist();
    setState(prevState => ({
      ...prevState,
      data: { ...prevState.data, [e.target.name]: e.target.value },
    }));
  };

  const handleSelectChange = (name, selectItem) => {
    setState(prevState => ({
      ...prevState,
      data: {
        ...prevState.data,
        [name]: selectItem.value,
      },
    }));
  };

  const handleSubmit = e => {
    e.preventDefault();
    const { data } = stateVal;
    const errors = validate(data);
    setState(prevState => ({ ...prevState, errors }));
    if (Object.keys(errors).length === 0) {
      setState(prevState => ({ ...prevState, loading: true }));
      const payload = { ...data, email: toLoginEmail(data.email) };
      if (data.guardianId) {
        return updateGuardian(payload)
          .then(() => {
            stateValReset();
            guardianUpdateSuccess('update');
          })
          .catch(err => setError(err));
      }
      return saveGuardian(payload)
        .then(() => {
          stateValReset();
          guardianUpdateSuccess('add');
        })
        .catch(err => setError(err));
    }
  };

  const setError = err => {
    setState(prevState => ({
      ...prevState,
      errors: {
        global: formResMessage(err),
      },
      loading: false,
    }));
  };

  const stateValReset = () => {
    setState(stateObj);
  };

  const formModalClose = () => {
    stateValReset();
    formModalCloseProp();
  };

  const validate = data => {
    const errors = {};
    if (validator.isEmpty(data.name)) {
      errors.name = 'Name cannot be empty';
    }
    if (validator.isEmpty(data.email)) {
      errors.email = 'Email cannot be empty';
    } else if (!validator.isEmail(toLoginEmail(data.email))) {
      errors.email = 'Invalid email';
    }
    if (validator.isEmpty(data.relation.toString().trim())) {
      errors.relation = 'Relation cannot be empty';
    }
    if (validator.isEmpty(data.guardianMobile.toString().trim())) {
      errors.guardianMobile = 'Mobile number cannot be empty';
    }
    if (validator.isEmpty(data.income.toString().trim())) {
      errors.income = 'Income cannot be empty';
    }
    if (validator.isEmpty(data.motherTongue.toString().trim())) {
      errors.motherTongue = 'Mother Tongue cannot be empty';
    }
    return errors;
  };

  const { data, relationArr, errors, loading } = stateVal;
  const thisData = (
    <Modal size="lg" isOpen={isModalOpen}>
      <form onSubmit={handleSubmit}>
        <ModalHeader>{data?.guardianId ? 'UPDATE GUARDIAN' : 'ADD GUARDIAN'}</ModalHeader>
        <ModalBody>
          {errors.global && <div className="mt-10 ml-15 mr-15 pad-12 alert alert-danger">{errors.global}</div>}
          <div className="content">
            <div className="container-fluid">
              <Row>
                <Col sm={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Name<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="name"
                      onChange={e => handleChange(e)}
                      value={data.name}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.name && <span className="err-msg">{errors.name}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Username or Email<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="email"
                      onChange={e => handleChange(e)}
                      value={data.email}
                      placeholder="Enter here..."
                      maxLength="50"
                      disabled={data?.guardianId}
                    />
                    {errors.email && <span className="err-msg">{errors.email}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Mobile number<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="guardianMobile"
                      onChange={e => handleChange(e)}
                      value={data.guardianMobile}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.guardianMobile && <span className="err-msg">{errors.guardianMobile}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Select Relation<sup> *</sup>
                    </Label>
                    <Select
                      value={data.relation ? { label: data.relation, value: data.relation } : null}
                      onChange={value => handleSelectChange('relation', value)}
                      options={relationArr}
                    />
                    {errors.relation && <span className="err-msg">{errors.relation}</span>}
                  </FormGroup>
                </Col>
                <Col sm={6}>
                  <FormGroup>
                    <Label htmlFor="">
                      Income<sup> *</sup>
                    </Label>
                    <Input
                      type="text"
                      name="income"
                      onChange={e => handleChange(e)}
                      value={data.income}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                    {errors.income && <span className="err-msg">{errors.income}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Select Mother Tongue or Native Language<sup> *</sup>
                    </Label>
                    <Select
                      value={data.motherTongue ? languages.find(dt => dt.value === data.motherTongue) : null}
                      onChange={value => handleSelectChange('motherTongue', value)}
                      options={languages}
                    />
                    {errors.motherTongue && <span className="err-msg">{errors.motherTongue}</span>}
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Education<sup> </sup>
                    </Label>
                    <Input
                      type="text"
                      name="education"
                      onChange={e => handleChange(e)}
                      value={data.education}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>
                  <FormGroup>
                    <Label htmlFor="">
                      Occupation<sup> </sup>
                    </Label>
                    <Input
                      type="text"
                      name="occupation"
                      onChange={e => handleChange(e)}
                      value={data.occupation}
                      placeholder="Enter here..."
                      maxLength="50"
                    />
                  </FormGroup>
                </Col>
              </Row>
            </div>
          </div>
        </ModalBody>
        <ModalFooter>
          <CustomButton type="submit" disabled={loading} loading={loading} />
          <CustomButton
            className="ml-2"
            type="button"
            color="default"
            disabled={loading}
            onClick={formModalClose}
            name="Cancel"
          />
        </ModalFooter>
      </form>
    </Modal>
  );
  return <div>{thisData}</div>;
};

export default GuardianFormModal;
