import React from 'react';
import { connect } from 'react-redux';
import { Card, CardBody, Table, NavItem, NavLink } from 'reactstrap';
import classnames from 'classnames';
import Select from 'react-select';
import Switch from '@material-ui/core/Switch';
import Grid from '@material-ui/core/Grid';
import CardMUI from '@material-ui/core/Card';
import CardContent from '@material-ui/core/CardContent';

import { Paper, Tab, Tabs } from '@material-ui/core';
import SchoolIcon from '@material-ui/icons/School';
import SettingsApplicationsIcon from '@material-ui/icons/SettingsApplications';
import { currencyArr } from '../School/components/SchoolFormModal.jsx';
import { fetchSchoolService } from '../../../actions/admin/schools.js';
import constants from '../../../config/constants.js';
import ConfirmModal from '../Common/ConfirmModal';
import { languages } from '../Guardian/components/GuardianFormModal.jsx';
import { showToast } from '../../../actions/admin/auth.js';
import { isLapView, store } from '../../../index.js';
import {
  fetchAttendanceConfigService,
  fetchPermissionModuleService,
  fetchSchoolCommonConfigService,
  saveAttendanceConfigService,
  updatePermissionModuleService,
  updateSchoolConfigService,
} from '../../../actions/admin/config.js';
import {
  convertModuleToName,
  formResMessage,
  getGlobalSchoolUtils,
  getLocalStore,
  setLocalStore,
} from '../../../utils/commonFunc.js';
import { ScrollTabPanel } from '../Reports/index.js';
import SettingsBrightnessIcon from '@material-ui/icons/SettingsBrightness';
import AccessTimeIcon from '@material-ui/icons/AccessTime';
import CommonTooltip from '../Common/CommonTooltip.jsx';
import { green } from '@material-ui/core/colors';
import { withStyles } from '@material-ui/styles';
import colors from 'config/colors.js';
import CustomInput from '../Common/CustomInput.jsx';
import CustomButton from '../../../components/CustomButton.jsx';
import moment from 'moment';
import { SkeletonBars } from 'views/admin/Common/Loader';

const tabList = [
  { tabIndex: 0, tabTitle: 'About School', query: 'school-config', icon: <SchoolIcon /> },
  { tabIndex: 1, tabTitle: 'Common', query: 'common-config', icon: <SettingsApplicationsIcon /> },
  { tabIndex: 2, tabTitle: 'Permissions', query: 'module-permission', icon: <SettingsBrightnessIcon /> },
  { tabIndex: 3, tabTitle: 'Attendance', query: 'attendance-config', icon: <AccessTimeIcon /> },
];

// Backend (AttendanceConfigurationDto) stores/returns time as "HH:mm:ss"; the native
// <input type="time"> works in "HH:mm" - convert at the edges rather than everywhere.
const toTimeInputValue = timeStr => (timeStr ? timeStr.slice(0, 5) : '');
const toApiTimeValue = timeStr => (timeStr ? `${timeStr}:00` : '');

const teacherOptions = [
  { label: 'Teacher', value: 'TEACHER' },
  { label: 'Professor', value: 'PROFESSOR' },
  { label: 'Staff', value: 'STAFF' },
  { label: 'Employee', value: 'EMPLOYEE' },
];

const classOptions = [
  { label: 'Class', value: 'CLASS' },
  { label: 'Course', value: 'COURSE' },
];

const regNoOptions = [
  { label: 'Reg No', value: 'REG_NO' },
  { label: 'Admission No', value: 'ADMISSION_NO' },
];

export const commonConfigs = [
  { label: 'School Language', name: 'SCHOOL_LANGUAGE', type: 'select', value: 'EN' },
  { label: 'Label for Teacher', name: 'LABEL_TEACHER', type: 'select', value: 'TEACHER', options: teacherOptions },
  { label: 'Label for Class', name: 'LABEL_CLASS', type: 'select', value: 'CLASS', options: classOptions },
  { label: 'Label for Reg No', name: 'LABEL_REG_NO', type: 'select', value: 'REG_NO', options: regNoOptions },
  { label: 'Mobile App Notifications', name: 'ENABLE_APP_NOTIFICATION', type: 'checkbox', value: 'DISABLED' },
  // { label: 'Fees Payments in Mobile app', name: 'PAYMENTS_IN_APP', type: 'checkbox', value: 'DISABLED' },
  { label: 'Text Messages to Parents', name: 'TEXT_MSG_TO_PARENTS', type: 'checkbox', value: 'DISABLED' },
  // { label: 'WhatsApp Messages to Parents', name: 'WHATSAPP_MSG_TO_PARENTS', type: 'checkbox', value: 'DISABLED' },
  { label: 'GPS Tracker in School bus', name: 'GPS_TRACK', type: 'checkbox', value: 'DISABLED' },
];

let timer;
let clrTimer;
let reloaded = false;
class ConfigPage extends React.Component {
  constructor() {
    super();
    this.state = {
      confirmModalOpen: false,
      assignConfirmModalOpen: false,
      schoolId: 0,
      activeTab: 0,
      isConfirmModalOpen: false,
      message: '',
      updateItem: {
        itemName: '',
        value: null,
      },
      permModules: [],
      attendanceConfig: {
        attendanceConfigurationId: null,
        inTime: '',
        outTime: '',
        latitude: '',
        longitude: '',
        attendanceDistanceMeter: '',
      },
      attendanceConfigFetching: false,
      attendanceConfigSaving: false,
      attendanceLocationFetching: false,
      attendanceLocationLocked: false,
      attendanceConfigError: '',
    };
  }

  componentDidMount() {
    const {
      location: { search },
    } = this.props;
    if (search) {
      const cTab = tabList.find(dto => search.includes(dto.query));
      if (cTab) {
        this.toggleActivityTab(cTab.tabIndex);
      } else {
        this.toggleActivityTab(0);
      }
    } else {
      this.toggleActivityTab(0);
    }

    const globalSchool = getGlobalSchoolUtils();
    const schoolId = globalSchool?.schoolId || null;
    if (schoolId) {
      this.setState({ schoolId }, () => {
        this.fetchOneSchool();
        this.fetchSchoolCommonConfig();
      });
    } else {
      this.showWarning('Please select school', 'warning');
    }
  }

  componentDidUpdate(prevProps) {
    if (prevProps.permModules !== this.props.permModules) {
      this.setState(prevState => ({ ...prevState, permModules: this.props.permModules }));
    }
  }

  fetchOneSchool = () => {
    this.props.fetchSchool({
      schoolId: this.state.schoolId,
      token: this.props.loggedUserToken,
    });
  };

  showWarning = (message, type) => {
    this.setState({
      confirmModalOpen: false,
      assignConfirmModalOpen: false,
    });
    store.dispatch(showToast(message, type));
  };

  fetchPermModules = () => {
    const globalSchool = getGlobalSchoolUtils();
    this.props.fetchPermModules({
      schoolId: this.state.schoolId || globalSchool.schoolId,
      token: this.props.loggedUserToken,
    });
  };

  toggleActivityTab = tabIndex => {
    if (this.state.activeTab !== tabIndex) {
      this.setState({ activeTab: tabIndex });
      const cTab = tabList.find(dto => dto.tabIndex === tabIndex);
      this.props.history.push(`${this.props.location.pathname}?${cTab.query}`);
      if (tabIndex === 2) {
        this.fetchPermModules();
      }
      if (tabIndex === 3) {
        this.fetchAttendanceConfig();
      }
    }
  };

  fetchAttendanceConfig = async () => {
    const globalSchool = getGlobalSchoolUtils();
    this.setState({ attendanceConfigFetching: true, attendanceConfigError: '' });
    const data = await this.props.fetchAttendanceConfig({
      schoolId: this.state.schoolId || globalSchool.schoolId,
      token: this.props.loggedUserToken,
    });
    this.setState({
      attendanceConfigFetching: false,
      attendanceConfig: {
        attendanceConfigurationId: data?.attendanceConfigurationId || null,
        inTime: toTimeInputValue(data?.inTime),
        outTime: toTimeInputValue(data?.outTime),
        latitude: data?.latitude ?? '',
        longitude: data?.longitude ?? '',
        attendanceDistanceMeter: data?.attendanceDistanceMeter ?? '',
      },
      // a school's location can be added once; after that only support can change it
      attendanceLocationLocked: !!(Number(data?.latitude) || Number(data?.longitude)),
    });
  };

  handleAttendanceTimeChange = (name, value) => {
    this.setState(prevState => ({
      ...prevState,
      attendanceConfig: { ...prevState.attendanceConfig, [name]: value },
      attendanceConfigError: '',
    }));
  };

  useCurrentLocationForAttendance = () => {
    if (!navigator.geolocation) {
      this.setState({ attendanceConfigError: 'Location is not supported by this browser' });
      return;
    }
    this.setState({ attendanceLocationFetching: true, attendanceConfigError: '' });
    navigator.geolocation.getCurrentPosition(
      position => {
        this.setState(prevState => ({
          ...prevState,
          attendanceConfig: {
            ...prevState.attendanceConfig,
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
          },
          attendanceLocationFetching: false,
          attendanceConfigError: '',
        }));
      },
      error =>
        this.setState({
          attendanceLocationFetching: false,
          attendanceConfigError: `Unable to fetch current location: ${error.message}`,
        })
    );
  };

  saveAttendanceConfig = async () => {
    const globalSchool = getGlobalSchoolUtils();
    const { attendanceConfig } = this.state;
    const { inTime, outTime, latitude, longitude, attendanceDistanceMeter } = attendanceConfig;
    if (!inTime || !outTime) {
      this.setState({ attendanceConfigError: 'Both in time and out time are required' });
      return;
    }
    if (!moment(outTime, 'HH:mm').isAfter(moment(inTime, 'HH:mm'))) {
      this.setState({ attendanceConfigError: 'Out time must be after in time' });
      return;
    }
    if (latitude === '' || longitude === '') {
      this.setState({ attendanceConfigError: 'Latitude and longitude are required' });
      return;
    }
    if (attendanceDistanceMeter === '' || Number(attendanceDistanceMeter) <= 0) {
      this.setState({ attendanceConfigError: 'Attendance radius is required' });
      return;
    }
    if (Number(attendanceDistanceMeter) > 1000) {
      this.setState({ attendanceConfigError: 'Attendance radius cannot be more than 1000 meters (1km)' });
      return;
    }
    this.setState({ attendanceConfigSaving: true, attendanceConfigError: '' });
    try {
      await this.props.saveAttendanceConfig({
        token: this.props.loggedUserToken,
        postData: {
          attendanceConfigurationId: attendanceConfig.attendanceConfigurationId || undefined,
          schoolId: this.state.schoolId || globalSchool.schoolId,
          inTime: toApiTimeValue(inTime),
          outTime: toApiTimeValue(outTime),
          status: 'ACTIVE',
          latitude: Number(latitude),
          longitude: Number(longitude),
          attendanceDistanceMeter: Number(attendanceDistanceMeter),
        },
      });
      this.showWarning('Attendance settings updated', 'success');
      this.fetchAttendanceConfig();
    } catch (err) {
      this.setState({ attendanceConfigError: formResMessage(err) });
    }
    this.setState({ attendanceConfigSaving: false });
  };

  renderActivityTabs = () => {
    return tabList.map(item => {
      return (
        <NavItem className="tabNavItem" key={item.tabIndex}>
          <NavLink
            className={classnames({ active: this.state.activeTab === item.tabIndex })}
            onClick={() => {
              this.toggleActivityTab(item.tabIndex);
            }}
            style={
              this.state.activeTab === item.tabIndex
                ? { fontWeight: 'bold', color: 'blue', border: '1px solid aqua' }
                : null
            }>
            {item.tabTitle}
          </NavLink>
        </NavItem>
      );
    });
  };

  setError = err => {
    this.showWarning(formResMessage(err), 'error');
  };

  isExistItem = (itemName, passList) => {
    const globalSchool = getGlobalSchoolUtils();
    const { commonConfigList = passList, loggedUserSchool = globalSchool.schoolId } = this.props;
    return commonConfigList?.find(
      el => el?.configName?.toUpperCase() === itemName?.toUpperCase() && el?.schoolId === loggedUserSchool
    );
  };

  fetchSchoolCommonConfig = async (refetchAgain, isTeacherOrClassChanged) => {
    const { commonConfigList, fetchSchoolCommonConfig, loggedUserToken } = this.props;
    const commonConfigStore = getLocalStore('commonConfig');
    clearTimeout(timer);
    const res =
      refetchAgain || !commonConfigList?.length
        ? await fetchSchoolCommonConfig({
            schoolId: this.state.schoolId,
            token: loggedUserToken,
          })
        : commonConfigList;
    if (res?.length) {
      if (isTeacherOrClassChanged || !commonConfigStore?.length) {
        setLocalStore('commonConfig', res);
        if (!reloaded) {
          reloaded = true;
          // window?.location?.reload();
        }
      }
      timer = setTimeout(() => {
        const isExist = this.isExistItem('SCHOOL_LANGUAGE', res);
        if (!isExist) {
          this.updateSchoolConfig(isExist, { itemName: 'SCHOOL_LANGUAGE', value: 'EN' });
        }
      }, 2000);
    }
  };

  cancelConfirm = () => {
    this.setState(prevState => ({
      ...prevState,
      isConfirmModalOpen: false,
      message: '',
      updateItem: { itemName: '', value: null },
    }));
  };

  updateSchoolConfig = (isExist, manualUpdateItem = null) => {
    const globalSchool = getGlobalSchoolUtils();
    const updateItem = manualUpdateItem || this.state.updateItem;
    const updateValue = val => {
      if (typeof val === 'boolean') {
        return val ? 'ENABLED' : 'DISABLED';
      }
      if (typeof val === 'object') {
        return val.value;
      }
      return val;
    };
    this.props
      .updateSchoolConfig({
        method: isExist ? 'put' : 'post',
        postData: {
          configId: isExist ? isExist?.configId : null,
          configName: updateItem?.itemName,
          configValue: updateValue(updateItem?.value),
          schoolId: this.state.schoolId || globalSchool?.schoolId,
        },
        token: this.props.loggedUserToken,
      })
      .then(() => {
        this.cancelConfirm();
        const isTeacherOrClassChanged = ['LABEL_TEACHER', 'LABEL_CLASS', 'LABEL_REG_NO'].includes(updateItem?.itemName);
        this.fetchSchoolCommonConfig(true, isTeacherOrClassChanged);
        // courseStatic/employeeStatic/regNoStatic (config/constants.js) are read from
        // localStorage once when the app first loads, not on every render, so a page still open
        // from before this save keeps showing the old label until it's reloaded - reload it here
        // automatically instead of relying on the admin to do it themselves.
        if (isTeacherOrClassChanged) {
          this.showWarning('Saved. Refreshing to apply this label everywhere...', 'success');
          setTimeout(() => window.location.reload(), 1200);
        }
      });
  };

  updateConfig = (itemName, value) => {
    this.setState(prevState => ({
      ...prevState,
      isConfirmModalOpen: true,
      message: 'Are you sure you want to update?',
      updateItem: { itemName, value },
    }));
  };

  componentWillUnmount() {
    if (timer) {
      clearTimeout(timer);
    }
  }

  updatePermModule = (moduleName, index, name, isChecked) => {
    clearTimeout(clrTimer);
    const globalSchool = getGlobalSchoolUtils();
    let stateModules = [...this.state.permModules];
    stateModules[index] = {
      ...stateModules[index],
      [name]: isChecked === true ? 'YES' : 'NO',
    };
    this.setState(prevState => ({
      ...prevState,
      permModules: stateModules,
    }));
    clrTimer = setTimeout(async () => {
      await this.props.updatePermModules({
        token: this.props.loggedUserToken,
        postData: stateModules,
        schoolId: this.state.schoolId || globalSchool.schoolId,
      });
    }, 3000);
  };

  setLocalState = (formParam, value) => {
    this.setState(prevState => ({
      ...prevState,
      [formParam]: value,
    }));
  };

  confirmUpdate = async () => {
    const { updateItem } = this.state;
    const isExist = this.isExistItem(updateItem?.itemName);
    this.updateSchoolConfig(isExist);
  };

  render() {
    const { activeTab, isConfirmModalOpen, message, permModules } = this.state;
    const { loggedUserRole, school } = this.props;
    const noDataFoundDiv = (
      <tr className="text-center">
        <td colSpan="7" style={{ paddingTop: 30, fontWeight: 'bold' }}>
          NO DATA FOUND
        </td>
      </tr>
    );
    const isTeacher = loggedUserRole === constants.roles.teacher;

    const PurpleSwitch = withStyles({
      switchBase: {
        '&$checked': {
          color: green[500],
        },
        '&$checked + $track': {
          backgroundColor: green[500],
        },
      },
      checked: {},
      track: {},
    })(Switch);

    const CustomSwitch = passProps => {
      return (
        <>
          <CommonTooltip content={passProps.value === 'YES' ? 'Enabled' : 'Disabled'}>
            <PurpleSwitch
              size="small"
              inputProps={{ 'aria-label': 'secondary checkbox' }}
              id={passProps?.name?.toString()}
              name={passProps.name}
              checked={passProps?.value === 'YES'}
              onChange={e => {
                this.updatePermModule(passProps.moduleName, passProps.index, passProps.name, e.target.checked);
              }}
              disabled={isTeacher}
            />
          </CommonTooltip>
        </>
      );
    };
    const thirdTabDiv = (
      <CardMUI variant="outlined">
        <CardContent>
          <Grid container spacing={2}>
            <Grid item sm={2} xs={2} md={2}>
              <p>
                <b>School name</b>
              </p>
            </Grid>
            <Grid item sm={4} xs={4} md={4}>
              <p className="card-category">{school.schoolName || '--'}</p>
            </Grid>

            <Grid item sm={2} xs={2} md={2}>
              <p>
                <b>School code</b>
              </p>
            </Grid>
            <Grid item sm={4} xs={4} md={4}>
              <p className="card-category">{school.schoolCode || '--'}</p>
            </Grid>

            <Grid item sm={2} xs={2} md={2}>
              <p>
                <b>Phone</b>
              </p>
            </Grid>
            <Grid item sm={4} xs={4} md={4}>
              <p className="card-category">{school.phoneNumber || '--'}</p>
            </Grid>

            <Grid item sm={2} xs={2} md={2}>
              <p>
                <b>Address</b>
              </p>
            </Grid>
            <Grid item sm={4} xs={4} md={4}>
              <p className="card-category">{school.address ? `${school.address}, ${school.country}` : '--'}</p>
            </Grid>

            <Grid item sm={2} xs={2} md={2}>
              <p>
                <b>Language</b>
              </p>
            </Grid>
            <Grid item sm={4} xs={4} md={4}>
              <p className="card-category">{languages.find(dt => dt.value === school.language)?.label || '--'}</p>
            </Grid>

            <Grid item sm={2} xs={2} md={2}>
              <p>
                <b>Currency type</b>
              </p>
            </Grid>
            <Grid item sm={4} xs={4} md={4}>
              <p className="card-category">{currencyArr.find(dt => dt.value === school.currencyType)?.label || '--'}</p>
            </Grid>

            <Grid item sm={2} xs={2} md={2}>
              <p>
                <b>Fax number</b>
              </p>
            </Grid>
            <Grid item sm={4} xs={4} md={4}>
              <p className="card-category">{school.faxNumber || '--'}</p>
            </Grid>

            <Grid item sm={2} xs={2} md={2}>
              <p>
                <b>Short name</b>
              </p>
            </Grid>
            <Grid item sm={4} xs={4} md={4}>
              <p className="card-category">{school?.schoolShortName || '--'}</p>
            </Grid>
          </Grid>
        </CardContent>
      </CardMUI>
    );
    const fourthTabDiv = (
      <>
        <Card style={{ marginTop: 10 }}>
          <CardBody>
            <Table size="sm" responsive>
              <thead className="text-primary">
                <tr>
                  <th>Config Name</th>
                  <th>Config value</th>
                </tr>
              </thead>
              <tbody>
                {commonConfigs.map((item, i) => {
                  const isExist = this.isExistItem(item.name);
                  const value = isExist ? isExist.configValue : item.value;
                  return (
                    <tr key={i}>
                      <td>{item.label}</td>
                      <td>{value}</td>
                      <td style={{ textAlign: 'center' }}>
                        {item.type === 'checkbox' ? (
                          <Switch
                            inputProps={{ 'aria-label': 'secondary checkbox' }}
                            id={i.toString()}
                            name="customSwitch"
                            checked={value === 'ENABLED'}
                            onChange={e => {
                              this.updateConfig(item.name, e.target.checked);
                            }}
                            disabled={isTeacher}
                          />
                        ) : (
                          <Select
                            value={value ? (item.options || languages)?.find(dt => dt.value === value) : null}
                            onChange={value => {
                              this.updateConfig(item.name, value);
                            }}
                            options={item.options || languages}
                            isDisabled={isTeacher}
                          />
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </Table>
          </CardBody>
        </Card>
      </>
    );
    const fifthTabDiv = (
      <div>
        <CardMUI variant="outlined">
          <CardContent>
            <Table size="sm" responsive>
              <thead className="text-primary">
                <tr>
                  <th>Module</th>
                  <th className="text-center">Push notification</th>
                  <th className="text-center">Text SMS</th>
                  <th className="text-center">WhatsApp Message</th>
                  <th className="text-center">Email</th>
                </tr>
              </thead>
              <tbody>
                {permModules?.length
                  ? permModules?.map((item, i) => {
                      return (
                        <tr key={i}>
                          <td>{convertModuleToName(item?.moduleName)}</td>
                          {['allowPushNotify', 'allowSms', 'allowWhatsApp', 'allowEmail'].map((el1, i1) => (
                            <td className="text-center" key={i1}>
                              <CustomSwitch name={el1} value={item?.[el1]} moduleName={item?.moduleName} index={i} />
                            </td>
                          ))}
                        </tr>
                      );
                    })
                  : noDataFoundDiv}
              </tbody>
            </Table>
          </CardContent>
        </CardMUI>
      </div>
    );

    const {
      attendanceConfig,
      attendanceConfigFetching,
      attendanceConfigSaving,
      attendanceLocationFetching,
      attendanceLocationLocked,
      attendanceConfigError,
    } = this.state;
    const sixthTabDiv = (
      <CardMUI variant="outlined">
        <CardContent>
          {attendanceConfigFetching ? (
            <SkeletonBars bars={4} />
          ) : (
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <Grid container spacing={2}>
                  <Grid item sm={6} xs={12} md={4}>
                    <CustomInput
                      label="In time"
                      name="inTime"
                      type="time"
                      value={attendanceConfig.inTime}
                      onChange={this.handleAttendanceTimeChange}
                      disabled={isTeacher}
                    />
                  </Grid>
                  <Grid item sm={6} xs={12} md={4}>
                    <CustomInput
                      label="Out time"
                      name="outTime"
                      type="time"
                      value={attendanceConfig.outTime}
                      onChange={this.handleAttendanceTimeChange}
                      disabled={isTeacher}
                    />
                  </Grid>
                </Grid>
              </Grid>
              <Grid item xs={12}>
                <Grid container spacing={2}>
                  <Grid item sm={4} xs={12} md={3}>
                    <CustomInput
                      label="Latitude"
                      name="latitude"
                      type="number"
                      value={attendanceConfig.latitude}
                      onChange={this.handleAttendanceTimeChange}
                      disabled={isTeacher || attendanceLocationLocked}
                    />
                  </Grid>
                  <Grid item sm={4} xs={12} md={3}>
                    <CustomInput
                      label="Longitude"
                      name="longitude"
                      type="number"
                      value={attendanceConfig.longitude}
                      onChange={this.handleAttendanceTimeChange}
                      disabled={isTeacher || attendanceLocationLocked}
                    />
                  </Grid>
                  {!isTeacher && !attendanceLocationLocked && (
                    <Grid
                      item
                      sm={4}
                      xs={12}
                      md={3}
                      style={{ display: 'flex', alignItems: 'flex-end', paddingBottom: 16 }}>
                      <CustomButton
                        name={attendanceLocationFetching ? 'Fetching location...' : 'Use my current location'}
                        variant="outlined"
                        color="default"
                        disabled={attendanceLocationFetching}
                        loading={attendanceLocationFetching}
                        showLoader
                        onClick={this.useCurrentLocationForAttendance}
                      />
                    </Grid>
                  )}
                </Grid>
                {attendanceLocationLocked && (
                  <div style={{ fontSize: 12, color: '#6b778a' }}>
                    <i className="fas fa-lock mr-1" />
                    The school location is set. A location can be added once - to update it, please contact support.
                  </div>
                )}
              </Grid>
              <Grid item xs={12}>
                <Grid container spacing={2}>
                  <Grid item sm={4} xs={12} md={3}>
                    <CustomInput
                      label="Attendance radius (meters, max 1000)"
                      name="attendanceDistanceMeter"
                      type="number"
                      value={attendanceConfig.attendanceDistanceMeter}
                      onChange={this.handleAttendanceTimeChange}
                      disabled={isTeacher}
                    />
                  </Grid>
                </Grid>
              </Grid>
              <Grid item xs={12}>
                {attendanceConfigError && <div className="err-msg mb-2">{attendanceConfigError}</div>}
                {!isTeacher && (
                  <CustomButton
                    name="Save"
                    disabled={attendanceConfigSaving}
                    loading={attendanceConfigSaving}
                    showLoader
                    onClick={this.saveAttendanceConfig}
                    style={attendanceConfigSaving ? undefined : { backgroundColor: colors.accent, color: colors.white }}
                  />
                )}
              </Grid>
            </Grid>
          )}
        </CardContent>
      </CardMUI>
    );

    return (
      <>
        <div className="content">
          <Paper square>
            <Tabs
              value={activeTab}
              onChange={(e, tabIndex) => this.toggleActivityTab(tabIndex)}
              indicatorColor=""
              textColor="inherit"
              variant={isLapView ? 'fullWidth' : 'scrollable'}
              scrollButtons="on"
              aria-label="scrollable force tabs example">
              {tabList.map((item, i) => {
                return (
                  <Tab
                    key={i}
                    icon={item.icon}
                    label={item.tabTitle}
                    style={{
                      fontWeight: 'bold',
                      color: activeTab === item.tabIndex ? colors.accent : '',
                      borderBottom: activeTab === item.tabIndex ? `3px solid ${colors.accent}` : '',
                    }}
                  />
                );
              })}
            </Tabs>
          </Paper>
          <ScrollTabPanel value={activeTab} index={0}>
            <br />
            {thirdTabDiv}
          </ScrollTabPanel>
          <ScrollTabPanel value={activeTab} index={1}>
            <br />
            {fourthTabDiv}
          </ScrollTabPanel>
          <ScrollTabPanel value={activeTab} index={2}>
            <br />
            {fifthTabDiv}
          </ScrollTabPanel>
          <ScrollTabPanel value={activeTab} index={3}>
            <br />
            {sixthTabDiv}
          </ScrollTabPanel>
        </div>
        <ConfirmModal
          confirmModalOpen={isConfirmModalOpen}
          confirmMessage={message}
          deleteConfirm={this.confirmUpdate}
          deleteCancel={this.cancelConfirm}
        />
      </>
    );
  }
}

const mapStateToProps = state => {
  return {
    loggedUserId: state.auth.loggedUserId,
    loggedUserToken: state.auth.loggedUserToken,
    loggedUserRole: state.auth.loggedUserRole,
    loggedUserSchool: state.auth.loggedUserSchool || undefined,
    school: state.schools.school,
    // Config
    commonConfigList: state.config.commonConfigList,
    permModules: state.config.permModules,
  };
};

const mapDispatchToProps = dispatch => {
  return {
    fetchSchool: data => dispatch(fetchSchoolService(data)),
    fetchSchoolCommonConfig: data => dispatch(fetchSchoolCommonConfigService(data)),
    updateSchoolConfig: data => dispatch(updateSchoolConfigService(data)),
    fetchPermModules: data => dispatch(fetchPermissionModuleService(data)),
    updatePermModules: data => dispatch(updatePermissionModuleService(data)),
    fetchAttendanceConfig: data => dispatch(fetchAttendanceConfigService(data)),
    saveAttendanceConfig: data => dispatch(saveAttendanceConfigService(data)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(ConfigPage);
